INSERT INTO public.exercises (session_id, type, title_en, title_id, description_en, description_id,
  starter_code, solution_code, test_cases, hints_en, hints_id, difficulty, dataset_name, order_num)
SELECT s.id, 'sql', 'Roasted Beans, Most Expensive First', 'Roasted Beans, Termahal Dulu', 'Seduh sells six categories. List every product in the **Roasted Beans** category, most expensive first. Return exactly: `product_name`, `base_price`.', 'Seduh menjual enam kategori. Tampilkan semua produk kategori **Roasted Beans**, termahal dulu. Kembalikan tepat: `product_name`, `base_price`.',
  '-- Roasted Beans products, most expensive first
-- Return: product_name, base_price
', 'SELECT product_name, base_price FROM products WHERE category = ''Roasted Beans'' ORDER BY base_price DESC;',
